int check_auth_token(const char *authfile, const char *username, const char *otp_id, int verbose, FILE *debug_file) {
    FILE *fp = fopen(authfile, "r");
    if (!fp) {
        if (verbose && debug_file) {
            fprintf(debug_file, "Failed to open authorization file: %s\n", authfile);
        }
        return AUTH_ERROR;
    }

    char line[1024];
    int user_found = 0;
    int token_found = 0;

    while (fgets(line, sizeof(line), fp)) {
        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\n' || line[0] == '\0') {
            continue;
        }

        // Check if the line starts with the username
        if (strncmp(line, username, strlen(username)) == 0 && isspace(line[strlen(username)])) {
            user_found = 1;
            // Check for token on the same line
            if (strstr(line, otp_id)) {
                token_found = 1;
                break;
            }
        }
    }

    fclose(fp);

    if (ferror(fp)) {
        if (verbose && debug_file) {
            fprintf(debug_file, "Error reading from authorization file: %s\n", authfile);
        }
        return AUTH_ERROR;
    }

    if (!user_found) {
        return AUTH_NOT_FOUND;
    }

    if (token_found) {
        return AUTH_FOUND;
    }

    return AUTH_NO_TOKENS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024
#define AUTH_FOUND 1
#define AUTH_NOT_FOUND 0
#define AUTH_NO_TOKENS -1
#define AUTH_ERROR -2

int check_token_in_authfile(const char *authfile, const char *username, const char *otp_id, int verbose, FILE *debug_file) {
    FILE *fp = fopen(authfile, "r");
    if (!fp) {
        if (verbose && debug_file) {
            fprintf(debug_file, "Failed to open authorization file: %s\n", authfile);
        }
        return AUTH_ERROR;
    }

    char line[MAX_LINE_LENGTH];
    int user_found = 0;
    int token_found = 0;

    while (fgets(line, sizeof(line), fp)) {
        char *comment = strchr(line, '#');
        if (comment) {
            *comment = '\0';
        }

        // Trim trailing whitespace
        char *end = line + strlen(line) - 1;
        while (end >= line && *end == ' ') {
            *end-- = '\0';
        }

        if (strlen(line) == 0) {
            continue;
        }

        if (strcmp(line, username) == 0) {
            user_found = 1;
        } else if (user_found && !token_found) {
            if (strcmp(line, otp_id) == 0) {
                token_found = 1;
            }
        }
    }

    fclose(fp);

    if (verbose && debug_file) {
        if (!user_found) {
            fprintf(debug_file, "Username not found: %s\n", username);
        } else if (!token_found) {
            fprintf(debug_file, "Token not found for user: %s\n", username);
        } else {
            fprintf(debug_file, "Token found for user: %s\n", username);
        }
    }

    if (!user_found) {
        return AUTH_NOT_FOUND;
    } else if (token_found) {
        return AUTH_FOUND;
    } else {
        return AUTH_NO_TOKENS;
    }
}
